// Shared brushes change colour in place: text, focus, editor documents and history survive a theme switch.
static class GlassTheme {
 static readonly Dictionary<string,string> light=new Dictionary<string,string>{{"Accent","#226DE5"},{"Ink","#1D3557"},{"Muted","#607C9D"},{"Background","#E7F0FC"},{"Panel","#BBFFFFFF"},{"Soft","#65FFFFFF"},{"Inset","#60E8F1FF"},{"Line","#90FFFFFF"},{"Hover","#BDDBECFF"},{"Pressed","#CCE0F7"},{"Popup","#F5F9FF"},{"Thumb","#7898BC"}};
 static readonly Dictionary<string,string> night=new Dictionary<string,string>{{"Accent","#91C5FF"},{"Ink","#E6F0FF"},{"Muted","#A2B8D4"},{"Background","#0B1528"},{"Panel","#C0172942"},{"Soft","#70203655"},{"Inset","#50102036"},{"Line","#536581A6"},{"Hover","#B02F507A"},{"Pressed","#375E8B"},{"Popup","#162A45"},{"Thumb","#5D7FA6"}};
 sealed class Colour : INotifyPropertyChanged {Color value;public Color Value{get{return value;}set{this.value=value;if(PropertyChanged!=null)PropertyChanged(this,new PropertyChangedEventArgs("Value"));}}public event PropertyChangedEventHandler PropertyChanged;}
 static readonly Dictionary<string,Colour> colours=new Dictionary<string,Colour>();
 static readonly Dictionary<string,SolidColorBrush> brushes=Make(light,true);
 static Dictionary<string,SolidColorBrush> Make(Dictionary<string,string> source,bool live=false){var result=new Dictionary<string,SolidColorBrush>();foreach(var p in source){var color=(Color)ColorConverter.ConvertFromString(p.Value);var brush=new SolidColorBrush(color);if(live){var item=new Colour{Value=color};colours[p.Key]=item;BindingOperations.SetBinding(brush,SolidColorBrush.ColorProperty,new Binding("Value"){Source=item});}result[p.Key]=brush;}return result;}
 public static Brush Brush(string key){return brushes[key];}
 public static Brush Alias(string color){string key=null;switch(color.ToUpperInvariant()){case "#F4F8FE":key="Background";break;case "#FFFFFF":case "#DBFFFFFF":key="Panel";break;case "#70FFFFFF":key="Soft";break;case "#F5F9FF":case "#F7FAFF":case "#EDF5FF":key="Inset";break;case "#EAF3FF":case "#DCEBFF":key="Hover";break;case "#DBE7F7":key="Line";break;case "#8893B4":key="Muted";break;}return key==null?null:Brush(key);}
 public static string Key(Brush brush){foreach(var pair in brushes)if(object.ReferenceEquals(pair.Value,brush))return pair.Key;return null;}
 public static void DarkScope(Window window){foreach(var p in Make(night))window.Resources["Glass"+p.Key]=p.Value;}
 public static void Apply(bool dark,bool animate){foreach(var pair in dark?night:light){var brush=brushes[pair.Key];var target=(Color)ColorConverter.ConvertFromString(pair.Value);var from=brush.Color;brush.BeginAnimation(SolidColorBrush.ColorProperty,null);colours[pair.Key].Value=target;if(animate)brush.BeginAnimation(SolidColorBrush.ColorProperty,new ColorAnimation(from,target,TimeSpan.FromMilliseconds(280)){FillBehavior=FillBehavior.Stop,EasingFunction=new CubicEase{EasingMode=EasingMode.EaseInOut}});}}
 public static void Install(){Application.Current.Resources=(ResourceDictionary)XamlReader.Parse(Styles);foreach(var p in brushes)Application.Current.Resources["Glass"+p.Key]=p.Value;Apply(AppSettings.Night,false);}
