 <Style x:Key='KeyboardFocusRing' TargetType='Control'><Setter Property='Template'><Setter.Value><ControlTemplate><Border Margin='2' CornerRadius='14' BorderBrush='{DynamicResource GlassAccent}' BorderThickness='1.5' IsHitTestVisible='False'/></ControlTemplate></Setter.Value></Setter></Style>
 <Style TargetType='Button'>
  <Setter Property='Background' Value='{DynamicResource GlassPanel}'/><Setter Property='Foreground' Value='{DynamicResource GlassInk}'/><Setter Property='BorderBrush' Value='{DynamicResource GlassLine}'/><Setter Property='BorderThickness' Value='1'/><Setter Property='FontSize' Value='12'/><Setter Property='MinHeight' Value='34'/><Setter Property='Padding' Value='14,7'/><Setter Property='Cursor' Value='Hand'/><Setter Property='FocusVisualStyle' Value='{StaticResource KeyboardFocusRing}'/>
  <Setter Property='Template'><Setter.Value><ControlTemplate TargetType='Button'><Border x:Name='b' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}' CornerRadius='16'><Grid><Border CornerRadius='16' BorderThickness='0,1,0,0' BorderBrush='#30FFFFFF' IsHitTestVisible='False'/><ContentPresenter HorizontalAlignment='Center' VerticalAlignment='Center' Margin='{TemplateBinding Padding}'/></Grid></Border><ControlTemplate.Triggers>
  <Trigger Property='IsMouseOver' Value='True'><Setter TargetName='b' Property='Background' Value='{DynamicResource GlassHover}'/><Trigger.EnterActions><BeginStoryboard><Storyboard><DoubleAnimation Storyboard.TargetName='b' Storyboard.TargetProperty='Opacity' From='.72' To='1' Duration='0:0:.16'/></Storyboard></BeginStoryboard></Trigger.EnterActions></Trigger>
  <Trigger Property='IsPressed' Value='True'><Setter TargetName='b' Property='Background' Value='{DynamicResource GlassPressed}'/><Setter TargetName='b' Property='Opacity' Value='.8'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='.38'/></Trigger>
  </ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter>
 </Style>
 <Style x:Key='PrimaryButton' TargetType='Button' BasedOn='{StaticResource {x:Type Button}}'><Setter Property='Background'><Setter.Value><LinearGradientBrush StartPoint='0,0' EndPoint='1,1'><GradientStop Color='#3285F8'/><GradientStop Color='#1958CD' Offset='1'/></LinearGradientBrush></Setter.Value></Setter><Setter Property='Foreground' Value='White'/><Setter Property='BorderBrush' Value='#559DDAFF'/><Setter Property='FontWeight' Value='SemiBold'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='Button'><Border x:Name='b' CornerRadius='17' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='1'><Grid><Border CornerRadius='17' BorderBrush='#60FFFFFF' BorderThickness='0,1,0,0'/><ContentPresenter Margin='{TemplateBinding Padding}' HorizontalAlignment='Center' VerticalAlignment='Center'/></Grid></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='b' Property='Opacity' Value='.88'/></Trigger><Trigger Property='IsPressed' Value='True'><Setter TargetName='b' Property='Opacity' Value='.7'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='.38'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
